1	package net.officefloor.hq.app.rollup;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.time.temporal.ChronoUnit;
7	import java.util.ArrayList;
8	import java.util.Collections;
9	import java.util.LinkedHashMap;
10	import java.util.List;
11	import java.util.Map;
12	import java.util.Objects;
13	import java.util.Optional;
14	import net.officefloor.hq.app.Audit;
15	import net.officefloor.hq.app.claim.Claim;
16	import net.officefloor.hq.app.claim.ClaimRepository;
17	import net.officefloor.hq.app.claim.ClaimStatus;
18	import net.officefloor.hq.app.person.Person;
19	import net.officefloor.hq.app.person.PersonRepository;
20	import net.officefloor.hq.app.rate.Rate;
21	import net.officefloor.hq.app.rate.RateRepository;
22	import net.officefloor.hq.app.settings.DatedSettings;
23	import net.officefloor.hq.app.sheet.Sheet;
24	import net.officefloor.hq.app.sheet.SheetRepository;
25	import org.springframework.stereotype.Service;
26	import org.springframework.transaction.annotation.Propagation;
27	import org.springframework.transaction.annotation.Transactional;
28	
29	/**
30	 * The figures each person on a sheet shows — what they have claimed (their OPEN, PENDING and SETTLED
31	 * claims, leaving out the OPEN and PENDING ones dated within one of their holds, or all of them once their
32	 * retirement date is reached on the sheet's today, that no statement binds)
33	 * and their due-total (the sum of what is due on those claims as each shows it, n/a when none has a figure and no rate of
34	 * their grade is in force on the sheet's today, and at most the sheet's cap in force on its today when it has one) and their
35	 * overdue-total (the sum of what is due on those that are OPEN or PENDING and past their due-by on the
36	 * sheet's today, as each shows it) — and the sheet's totals of them (the due-total and overdue-total
37	 * leave out the single highest and lowest person's figure when three or more people have one; a
38	 * due-total of n/a is no figure). A change that moves
39	 * any of them is followed in the audit by a ROLLUP line per person whose figures moved, then a TOTALS
40	 * line when the sheet's totals moved: take a {@link #snapshot} before the change, and
41	 * {@link #recordSince} it after the change has recorded its own lines.
42	 */
43	@Service
44	public class RollupService {
45	
46	    /** A due-total shown when there is none. */
47	    public static final String NONE = "n/a";
48	
49	    private final PersonRepository people;
50	    private final ClaimRepository claims;
51	    private final RateRepository rates;
52	    private final SheetRepository sheets;
53	    private final DatedSettings dated;
54	    private final Audit audit;
55	
56	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
57	            SheetRepository sheets, DatedSettings dated, Audit audit) {
58	        this.dated = dated;
59	        this.people = people;
60	        this.claims = claims;
61	        this.rates = rates;
62	        this.sheets = sheets;
63	        this.audit = audit;
64	    }
65	
66	    /** A person's figures, as shown. */
67	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
68	    }
69	
70	    /** The sheet's figures at one moment: each person's, by id in the order they were added, and the totals. */
71	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
72	    }
73	
74	    /** The figures the sheet shows now. */
75	    @Transactional(propagation = Propagation.MANDATORY)
76	    public Snapshot snapshot(String sheetId) {
77	        Sheet sheet = sheets.findById(sheetId).orElse(null);
78	        LocalDate today = sheet == null ? null : sheet.getToday();
79	        BigDecimal cap = sheet == null ? null : dated.cap(sheetId);
80	        List<Claim> all = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
81	        Map<Long, Figures> figures = new LinkedHashMap<>();
82	        BigDecimal claimedTotal = zero();
83	        List<BigDecimal> dueFigures = new ArrayList<>();
84	        List<BigDecimal> overdueFigures = new ArrayList<>();
85	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
86	            BigDecimal claimed = zero();
87	            BigDecimal due = zero();
88	            BigDecimal overdue = zero();
89	            boolean any = false;
90	            for (Claim claim : all) {
91	                if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person, today)) continue;
92	                claimed = claimed.add(claim.getAmount());
93	                BigDecimal figure = shownOf(claim, person);
94	                if (figure == null) continue;
95	                if (isOverdue(claim, today)) overdue = overdue.add(figure);
96	                due = due.add(figure);
97	                any = true;
98	            }
99	            due = cappedOf(due, cap);
100	            boolean rated = today != null && rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
101	            claimedTotal = claimedTotal.add(claimed);
102	            overdueFigures.add(overdue);
103	            if (any || rated) dueFigures.add(due);
104	            figures.put(person.getId(), new Figures(person.getName(), text(claimed), any || rated ? text(due) : NONE,
105	                    text(overdue)));
106	        }
107	        return new Snapshot(figures, text(claimedTotal), text(trimmedSum(dueFigures)), text(trimmedSum(overdueFigures)));
108	    }
109	
110	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
111	    static BigDecimal trimmedSum(List<BigDecimal> figures) {
112	        BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
113	        if (figures.size() < 3) return sum;
114	        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
115	    }
116	
117	    /** Record the ROLLUP and TOTALS lines for the figures that moved since {@code before}. */
118	    @Transactional(propagation = Propagation.MANDATORY)
119	    public void recordSince(String sheetId, String user, Snapshot before) {
120	        Snapshot after = snapshot(sheetId);
121	        after.people().forEach((id, now) -> {
122	            Figures then = before.people().get(id);
123	            if (then != null && then.claimed().equals(now.claimed()) && then.dueTotal().equals(now.dueTotal())
124	                    && then.overdueTotal().equals(now.overdueTotal())) return;
125	            audit.change("ROLLUP", sheetId, user, "person=" + now.name(), "claimed=" + now.claimed(),
126	                    "due-total=" + now.dueTotal(), "overdue-total=" + now.overdueTotal());
127	        });
128	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
129	                || !Objects.equals(before.dueTotal(), after.dueTotal())
130	                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
131	            audit.change("TOTALS", sheetId, user, "claimed-total=" + after.claimedTotal(),
132	                    "due-total=" + after.dueTotal(), "overdue-total=" + after.overdueTotal());
133	        }
134	    }
135	
136	    /** Whether the claim is overdue: OPEN or PENDING, not deferred on the sheet's {@code today}, and due
137	     * by a date before it. */
138	    public static boolean isOverdue(Claim claim, LocalDate today) {
139	        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
140	                && !claim.isDeferredOn(today) && claim.getDueBy().isBefore(today);
141	    }
142	
143	    /** A due-total as shown: at most {@code cap}, when there is one. */
144	    public static BigDecimal cappedOf(BigDecimal due, BigDecimal cap) {
145	        return cap == null ? due : due.min(cap);
146	    }
147	
148	    /** Whether the claim counts in the live totals on the sheet's {@code today}: OPEN, PENDING or
149	     * SETTLED, but not an OPEN claim deferred on {@code today}, nor OPEN or PENDING when it is dated
150	     * within one of its person's holds, or its person's retirement date is reached on {@code today}, and
151	     * no statement binds it (a PENDING claim is bound by none while it is). */
152	    public static boolean countsLive(Claim claim, Person person, LocalDate today) {
153	        return countsAs(claim, claim.getStatus(), person, today);
154	    }
155	
156	    /** Whether the claim would count in the live totals on the sheet's {@code today} were its status
157	     * {@code status} (see {@link #countsLive}). */
158	    public static boolean countsAs(Claim claim, ClaimStatus status, Person person, LocalDate today) {
159	        if (!status.counts()) return false;
160	        if (!status.isOpen()) return true;
161	        if (claim.isDeferredOn(today)) return false;
162	        boolean bound = claim.isStated() && status != ClaimStatus.PENDING;
163	        return bound || !(person.isHeldOn(claim.getDate()) || person.isRetiredOn(today));
164	    }
165	
166	    /** What a sheet's figures are worked out from: its today, the policy date, rates and dated settings in
167	     * force, and its claims. {@link #live} is the sheet as it stands; a sheet as it stood on an earlier
168	     * date gives its own. */
169	    public interface Basis {
170	
171	        /** The sheet's today; null when there is no sheet. */
172	        LocalDate today();
173	
174	        /** The policy date in force (see {@link Sheet#policyDateInForce()}); null when there is no sheet. */
175	        LocalDate policyDateInForce();
176	
177	        /** The grade's rate in force on the date (see {@link RateRepository#findInForce}). */
178	        Optional<Rate> rateInForce(String grade, LocalDate date);
179	
180	        /** The floor in force on the date; 0.00 when there is no sheet. */
181	        BigDecimal floorOn(LocalDate date);
182	
183	        /** The late percent in force on the date. */
184	        BigDecimal latePctOn(LocalDate date);
185	
186	        /** The cap in force on the sheet's today; null when there is none. */
187	        BigDecimal cap();
188	
189	        /** The person's claim with the number. */
190	        Optional<Claim> claimNumbered(Long personId, String number);
191	    }
192	
193	    /** The sheet as it stands. */
194	    public Basis live(String sheetId) {
195	        return new Basis() {
196	            private Sheet sheet() {
197	                return sheets.findById(sheetId).orElse(null);
198	            }
199	
200	            @Override
201	            public LocalDate today() {
202	                Sheet sheet = sheet();
203	                return sheet == null ? null : sheet.getToday();
204	            }
205	
206	            @Override
207	            public LocalDate policyDateInForce() {
208	                Sheet sheet = sheet();
209	                return sheet == null ? null : sheet.policyDateInForce();
210	            }
211	
212	            @Override
213	            public Optional<Rate> rateInForce(String grade, LocalDate date) {
214	                return rates.findInForce(sheetId, grade, date);
215	            }
216	
217	            @Override
218	            public BigDecimal floorOn(LocalDate date) {
219	                return sheet() == null ? zero() : dated.floorOn(sheetId, date);
220	            }
221	
222	            @Override
223	            public BigDecimal latePctOn(LocalDate date) {
224	                return dated.latePctOn(sheetId, date);
225	            }
226	
227	            @Override
228	            public BigDecimal cap() {
229	                return sheet() == null ? null : dated.cap(sheetId);
230	            }
231	
232	            @Override
233	            public Optional<Claim> claimNumbered(Long personId, String number) {
234	                return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, number);
235	            }
236	        };
237	    }
238	
239	    /** The person's due-total on {@code basis} from those of {@code theirs} that count on its today (see
240	     * {@link #countsLive}): the sum of what is due on them as each shows it, at most the cap; null (n/a)
241	     * when none has a figure and no rate of their grade is in force on its today. */
242	    public BigDecimal dueTotalOf(List<Claim> theirs, Person person, Basis basis) {
243	        LocalDate today = basis.today();
244	        BigDecimal due = zero();
245	        boolean any = false;
246	        for (Claim claim : theirs) {
247	            if (!countsLive(claim, person, today)) continue;
248	            BigDecimal figure = shownOf(claim, person, basis);
249	            if (figure == null) continue;
250	            due = due.add(figure);
251	            any = true;
252	        }
253	        boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
254	        return any || rated ? cappedOf(due, basis.cap()) : null;
255	    }
256	
257	    /** Whether the claim shows the figure fixed when it was settled at a rate: it is SETTLED, or was
258	     * voided once settled, and has one. */
259	    private static boolean frozen(Claim claim) {
260	        return claim.getSettledDue() != null
261	                && (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID);
262	    }
263	
264	    /** The figure the claim shows and totals now: what was fixed when it was settled at a rate (kept
265	     * once it is voided);
266	     * otherwise, unless it is PENDING (which no statement binds while it is), the figure a statement
267	     * bound it to; otherwise what is due on it at its person's rate.
268	     * Null when it has no figure. */
269	    public BigDecimal figureOf(Claim claim, Person person) {
270	        return figureOf(claim, person, live(claim.getSheetId()));
271	    }
272	
273	    /** The figure the claim shows on {@code basis} (see {@link #figureOf(Claim, Person)}). */
274	    public BigDecimal figureOf(Claim claim, Person person, Basis basis) {
275	        if (frozen(claim)) return claim.getSettledDue();
276	        if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) return claim.getStatedDue();
277	        return dueOf(claim, person, basis);
278	    }
279	
280	    /** What is due on the claim as it shows and totals now: what was fixed when it was settled at a
281	     * rate; otherwise its live due on its figure (see {@link #liveDueOf}); null when it has no figure. */
282	    public BigDecimal shownOf(Claim claim, Person person) {
283	        return shownOf(claim, person, live(claim.getSheetId()));
284	    }
285	
286	    /** What is due on the claim as it shows on {@code basis} (see {@link #shownOf(Claim, Person)}). */
287	    public BigDecimal shownOf(Claim claim, Person person, Basis basis) {
288	        BigDecimal figure = figureOf(claim, person, basis);
289	        if (frozen(claim)) return figure;
290	        return liveDueOf(claim, figure, basis);
291	    }
292	
293	    /** The live due on the claim whose figure (at its rate, or as a statement bound it) is
294	     * {@code figure}: the greater of the sheet's floor in force on the claim's date and that figure plus
295	     * its late charge (see {@link #lateChargeOf}); a correction has neither floor nor charge. Null when
296	     * {@code figure} is. */
297	    public BigDecimal liveDueOf(Claim claim, BigDecimal figure) {
298	        return liveDueOf(claim, figure, live(claim.getSheetId()));
299	    }
300	
301	    private BigDecimal liveDueOf(Claim claim, BigDecimal figure, Basis basis) {
302	        if (figure == null) return null;
303	        if (claim.isCorrection()) return figure;
304	        return floored(claim, figure.add(lateChargeOf(claim, figure, basis)), basis);
305	    }
306	
307	    /** {@code due}, at least the sheet's floor in force on the claim's date. */
308	    private static BigDecimal floored(Claim claim, BigDecimal due, Basis basis) {
309	        return due.max(basis.floorOn(claim.getDate()));
310	    }
311	
312	    /** The late charge on an OPEN or PENDING claim whose figure is {@code figure}: for every full 30 days the claim is overdue (past its due-by, fixed when it was added, on
313	     * the sheet's today), the sheet's late percent in force on that boundary date (the due-by plus 30, 60,
314	     * 90 ... days) of that figure, rounded to two decimals as the claim rounds, the charges added up (a boundary whose percent is 0.00 adds nothing) (see {@link #roundingOf}); 0.00 on a claim not OPEN or
315	     * PENDING, or not overdue (a deferred claim is not), and on a correction. A statement never binds it: it follows the sheet's today until the claim is settled. */
316	    public BigDecimal lateChargeOf(Claim claim, BigDecimal figure) {
317	        return lateChargeOf(claim, figure, live(claim.getSheetId()));
318	    }
319	
320	    private BigDecimal lateChargeOf(Claim claim, BigDecimal figure, Basis basis) {
321	        if (!claim.getStatus().isOpen()) return zero();
322	        return overdueChargeOf(claim, figure, basis);
323	    }
324	
325	    /** What would be due on the claim now were it an OPEN claim bound by no statement: its due at its
326	     * person's rate (see {@link #dueOf}) plus the late charge it would have then, at least the sheet's
327	     * floor in force on its date (a correction has neither); null when it would have no figure. */
328	    public BigDecimal openShownOf(Claim claim, Person person) {
329	        Basis basis = live(claim.getSheetId());
330	        BigDecimal figure = dueOf(claim, person, basis);
331	        if (figure == null || claim.isCorrection()) return figure;
332	        return floored(claim, figure.add(overdueChargeOf(claim, figure, basis)), basis);
333	    }
334	
335	    /** The late charge on a claim whose figure is {@code figure}, whatever its status (see {@link #lateChargeOf}). */
336	    private BigDecimal overdueChargeOf(Claim claim, BigDecimal figure, Basis basis) {
337	        if (claim.isCorrection()) return zero();
338	        LocalDate today = basis.today();
339	        if (today == null || claim.isDeferredOn(today)) return zero();
340	        long periods = Math.max(0, ChronoUnit.DAYS.between(claim.getDueBy(), today)) / 30;
341	        RoundingMode rounding = roundingOf(claim, basis);
342	        BigDecimal charge = zero();
343	        for (long k = 1; k <= periods; k++) {
344	            BigDecimal pct = basis.latePctOn(claim.getDueBy().plusDays(30 * k));
345	            if (pct.signum() == 0) continue;
346	            charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding));
347	        }
348	        return charge;
349	    }
350	
351	    /** What is due on the claim at its person's rate in force on the claim's date: amount times pct,
352	     * divided by 100, rounded to two decimals as the claim rounds (see {@link #roundingOf}) — the rate
353	     * figure alone, before any late charge or floor (see {@link #liveDueOf}); null when no
354	     * rate of the grade in force for them on the claim's date applies then. */
355	    public BigDecimal dueOf(Claim claim, Person person) {
356	        return dueOf(claim, person, live(claim.getSheetId()));
357	    }
358	
359	    private BigDecimal dueOf(Claim claim, Person person, Basis basis) {
360	        RoundingMode rounding = roundingOf(claim, basis);
361	        return basis.rateInForce(person.gradeOn(claim.getDate()), claim.getDate())
362	                .map(Rate::getPct)
363	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
364	                .orElse(null);
365	    }
366	
367	    /** How the claim's live figures round: half up when it is dated before the sheet's policy date in
368	     * force, half to even when on or after it. A correction rounds by the date of the claim it corrects. */
369	    private static RoundingMode roundingOf(Claim claim, Basis basis) {
370	        LocalDate policyDate = basis.policyDateInForce();
371	        if (policyDate == null) return RoundingMode.HALF_EVEN;
372	        LocalDate dated = claim.getDate();
373	        if (claim.isCorrection() && claim.getCorrects() != null) {
374	            dated = basis.claimNumbered(claim.getPersonId(), claim.getCorrects()).map(Claim::getDate).orElse(dated);
375	        }
376	        return dated.isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
377	    }
378	
379	    private static BigDecimal zero() {
380	        return BigDecimal.ZERO.setScale(2);
381	    }
382	
383	    private static String text(BigDecimal value) {
384	        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
385	    }
386	}
